package com.rpb.reservation.cards.purchase;
import com.rpb.reservation.cards.application.*;
import com.rpb.reservation.cards.application.CardDtos.*;
import com.rpb.reservation.cards.plan.CardPlanRepository;
import com.rpb.reservation.cards.entitlement.*;
import com.rpb.reservation.cards.command.CardCommands;
import com.rpb.reservation.catalog.application.ProductCatalogQuery;
import com.rpb.reservation.catalog.pricing.TaxCalculator;
import com.rpb.reservation.common.scope.StoreScope;
import com.rpb.reservation.customerauth.application.CustomerAuthPrincipal;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
@Transactional(readOnly=true)
public class PurchaseService {
 private final CardAccess access;private final CardPlanRepository plans;private final CardHoldingRepository cards;private final PurchaseRepository r;private final CardCommands commands;private final ProductCatalogQuery products;private final CardPaymentPort pay;private final Clock clock;
 public PurchaseService(CardAccess access,CardPlanRepository plans,CardHoldingRepository cards,PurchaseRepository r,CardCommands commands,ProductCatalogQuery products,CardPaymentPort pay,Clock clock){this.access=access;this.plans=plans;this.cards=cards;this.r=r;this.commands=commands;this.products=products;this.pay=pay;this.clock=clock;}
 public List<Purchase> staff(StoreScope s,CurrentActor a){return staff(s,a,null);}
 public List<Purchase> staff(StoreScope s,CurrentActor a,UUID before){access.staff(s,a,"wallet.cards.view",false);return r.list(s,null,before);}
 public Set<UUID> refundable(StoreScope s,CurrentActor a,Set<UUID> ids){access.staff(s,a,"wallet.cards.view",false);return r.refundable(s,ids);}
 public List<Purchase> own(StoreScope s,CustomerAuthPrincipal p){return own(s,p,null);}
 public List<Purchase> own(StoreScope s,CustomerAuthPrincipal p,UUID before){access.customer(s,p,false);return r.list(s,p.customerId(),before);}
 @Transactional public Purchase create(StoreScope s,CustomerAuthPrincipal p,PurchaseCreate c){access.customer(s,p,true);if(c==null||c.planId()==null)throw CardException.invalid();return commands.run(s,p.customerId(),"purchase.create",c.idempotencyKey(),c,Purchase.class,()->{var plan=plans.get(s,c.planId(),true);if(plan.kind().equals("stamp")||!plan.status().equals("active"))throw CardException.conflict("该卡不可购买");products.requireUsable(s,plan.productId(),"cards");long amount=TaxCalculator.calculate(plan.priceCents(),1,plan.taxMode(),plan.taxRate()).grossCents();return r.create(s,p.customerId(),plan,amount,clock.instant().plusSeconds(300));});}
 @Transactional public Purchase confirm(StoreScope s,CurrentActor a,UUID id,PaymentConfirm c){access.staff(s,a,"wallet.cards.sell",true);if(c==null||!c.verified())throw CardException.invalid();return commands.run(s,a.actorId(),"purchase.confirm",c.idempotencyKey(),Map.of("id",id,"body",c),Purchase.class,()->{var order=r.get(s,id,true);if(order.status().equals("issued"))return order;if(!order.status().equals("pending")||!order.expiresAt().isAfter(clock.instant()))throw CardException.conflict("购卡订单已过期或处理");var live=plans.get(s,order.planId(),true);if(!live.status().equals("active"))throw CardException.conflict("卡方案已停售，请先核对收款");products.requireUsable(s,live.productId(),"cards");if(c.amountCents()!=order.amountCents())throw CardException.invalid();access.requireCustomer(s,order.customerId());var receipt=pay.confirm(s,c);if(receipt.amountCents()!=order.amountCents())throw CardException.invalid();pay.claim(s,id,receipt);r.payment(s,id,receipt,"payment",a.actorId());var now=clock.instant();if(!order.expiresAt().isAfter(now))throw CardException.conflict("订单已过期，请核对收款");var p=order.snapshot();String zone=access.store(s).timezone();var h=cards.issue(s,order.customerId(),p,p.kind(),p.total(),p.dailyLimit(),zone,now,CardRules.expiry(now,zone,p.validDays()));cards.entry(s,h,"grant",p.total()==null?1:p.total(),0,p.total(),CardRules.day(now,zone),0,0,"purchase:"+id,null,a.actorId(),order.customerId(),"购买发卡",now);r.issue(s,id,h.id());return r.get(s,id,false);});}
 @Transactional public Purchase exception(StoreScope s,CurrentActor a,UUID id,ExceptionPayment c){access.staff(s,a,"wallet.cards.refund",false);if(c==null||c.payment()==null||!c.payment().verified()||c.reason()==null||c.reason().isBlank())throw CardException.invalid();return commands.run(s,a.actorId(),"purchase.exception",c.idempotencyKey(),Map.of("id",id,"body",c),Purchase.class,()->{var order=r.get(s,id,true);if(!order.status().equals("pending"))throw CardException.conflict("该单不能重复登记实收");if(c.payment().amountCents()!=order.amountCents())throw CardException.invalid();var receipt=pay.recovery(s,c.payment());if(receipt.amountCents()!=order.amountCents())throw CardException.invalid();pay.claim(s,id,receipt);r.payment(s,id,receipt,"payment",a.actorId());r.exception(s,id,false);return r.get(s,id,false);});}
 @Transactional public Purchase refund(StoreScope s,CurrentActor a,UUID id,Refund c){access.staff(s,a,"wallet.cards.refund",false);if(c==null||!c.verified()||c.reason()==null||c.reason().isBlank()||c.receipt()==null||c.receipt().isBlank())throw CardException.invalid();return commands.run(s,a.actorId(),"purchase.refund",c.idempotencyKey(),Map.of("id",id,"body",c),Purchase.class,()->{var order=r.get(s,id,true);if(order.status().equals("refunded")||order.status().equals("exception_refunded"))return order;if(order.status().equals("exception")){var original=r.receipt(s,id);r.payment(s,id,new PaymentReceipt(original.channel(),original.account(),c.receipt().trim().toUpperCase(Locale.ROOT),original.amountCents()),"refund",a.actorId());r.exception(s,id,true);return r.get(s,id,false);}if(!order.status().equals("issued"))throw CardException.conflict("购卡单不可退款");var h=cards.get(s,order.cardId(),true,clock.instant());boolean used=cards.hasRedemptions(s,h.id());if(used||!h.status().equals("active"))throw CardException.conflict("已使用的卡暂不支持退款");var original=r.receipt(s,id);r.payment(s,id,new PaymentReceipt(original.channel(),original.account(),c.receipt().trim().toUpperCase(Locale.ROOT),original.amountCents()),"refund",a.actorId());cards.update(s,h,h.remaining()==null?null:0,h.progress(),h.round());cards.status(s,h.id(),"refunded");cards.entry(s,h,"refund",h.initialTotal()==null?1:h.initialTotal(),h.remaining(),h.remaining()==null?null:0,CardRules.day(clock.instant(),h.timezone()),0,0,"refund:"+id,null,a.actorId(),null,c.reason(),clock.instant());r.refund(s,id);return r.get(s,id,false);});}
}
